<?php
declare(strict_types=1);
namespace EPejabat\Modules\EForms;
use EPejabat\Core\{AccessDenied,Support,Core,Database,Authorization,Ui,Upgrade,InstallationKey,Backup};
final class Web {
 private static function e(mixed $v):string{return Support::escape((string)$v);}
 private static function workspace(\PDO $p,int $u):string {
  $q=Core::text($_GET['q']??'',100,false);
  $page=max(1,min(10000,(int)($_GET['page']??1)));
  $sort=($_GET['sort']??'newest')==='title'?'title ASC,id DESC':'id DESC';
  $category=Core::text($_GET['category']??'',100,false);
  $catSql=$category!==''&&Visual::ready($p)?" AND EXISTS (SELECT 1 FROM eforms_versions cv JOIN eforms_visual_versions vv ON vv.version_id=cv.id WHERE cv.template_id=eforms_templates.id AND cv.version=(SELECT MAX(v2.version) FROM eforms_versions v2 WHERE v2.template_id=cv.template_id) AND JSON_UNQUOTE(JSON_EXTRACT(vv.definition_json,'$.category'))=?)":'';
  $createOrgs=self::orgs($p,$u,'submissions.create');
  $createIds=array_column($createOrgs,'id');
  $forms=$createIds?Database::query($p,"SELECT * FROM eforms_templates WHERE status='published' AND organisation_id IN (".implode(',',array_fill(0,count($createIds),'?')).") AND title LIKE ? $catSql ORDER BY $sort LIMIT 25 OFFSET ".(($page-1)*25),[...$createIds,'%'.$q.'%',...($catSql!==''?[$category]:[])])->fetchAll():[];
  $super=Authorization::super($p,$u);
  $canReview=$super||Authorization::any($p,$u,'eforms.submissions.review')||Authorization::any($p,$u,'eforms.submissions.manage');
  $canTemplates=$super||Authorization::any($p,$u,'eforms.templates.manage');

  $h='<section id="my-forms"><h2>Borang Saya / e-Forms</h2><p>Borang organisasi yang boleh dimulakan dalam skop akses anda.</p>';
  if($canTemplates)$h.='<p><a class="button" href="/eforms?studio=new">Cipta template borang</a></p>';
  $h.='<form method="get" class="filters"><label>Cari<input name="q" type="search" value="'.self::e($q).'"></label><label>Kategori<input name="category" value="'.self::e($category).'"></label><label>Susun<select name="sort"><option value="newest">Terbaharu</option><option value="title"'.(($_GET['sort']??'')==='title'?' selected':'').'>Tajuk</option></select></label><button>Cari</button></form><div class="eforms-cards">';
  foreach($forms as $form){
   $h.='<article class="card"><h3>'.self::e($form['title']).'</h3>'.self::form('new','<input type="hidden" name="id" value="'.$form['id'].'">','Buka draft baharu');
   if($super||Authorization::allowed($p,$u,'eforms.templates.manage',(int)$form['organisation_id']))$h.='<a href="/eforms?studio='.$form['id'].'">Edit template</a>';
   $h.='</article>';
  }
  if(!$forms)$h.='<p class="notice">Tiada borang tersedia dalam skop akses anda.</p>';
  $h.='</div></section>';

  $rows=Database::query($p,"SELECT s.id,s.status,s.updated_at,s.step_index,v.workflow_json,t.title,s.organisation_id,s.applicant_id FROM eforms_submissions s JOIN eforms_versions v ON v.id=s.version_id JOIN eforms_templates t ON t.id=v.template_id WHERE t.title LIKE ? ORDER BY s.id DESC",['%'.$q.'%'])->fetchAll();
  $mine=[];$tracked=[];$queue=[];
  foreach($rows as $row){
   try{Service::get($p,$u,(int)$row['id']);}catch(\RuntimeException $e){continue;}
   if((int)$row['applicant_id']===$u){$mine[]=$row;continue;}
   $tracked[]=$row;
   $steps=json_decode($row['workflow_json'],true);
   $current=is_array($steps)?($steps[(int)$row['step_index']]['user_id']??0):0;
   if($row['status']==='submitted'&&(int)$current===$u&&($super||Authorization::allowed($p,$u,'eforms.submissions.review',(int)$row['organisation_id'])))$queue[]=$row;
  }
  $h.='<section id="my-submissions" class="card"><h2>Permohonan Saya</h2>'.self::submissionTable(array_slice($mine,($page-1)*25,25),'Tiada permohonan peribadi direkodkan.').'</section>';

  if($canReview){
   $h.='<section id="approval-queue" class="card"><h2>Semakan &amp; Kelulusan (Approval Queue)</h2>'.self::submissionTable(array_slice($queue,0,25),'Tiada permohonan menunggu tindakan anda.',true).'</section>';
   $h.='<section id="submission-list" class="card"><h2>Senarai Submission</h2>'.self::submissionTable(array_slice($tracked,($page-1)*25,25),'Tiada submission dalam skop pentadbiran anda.').'<p>'.count($tracked).' submission dalam akses anda.</p></section>';
  }

  if($canReview||$canTemplates){
   $statusOrgs=[];
   foreach(['submissions.review','submissions.manage','templates.manage'] as $permission){
    if(!$super&&!Authorization::any($p,$u,'eforms.'.$permission))continue;
    foreach(self::orgs($p,$u,$permission) as $org)$statusOrgs[(int)$org['id']]=$org;
   }
   $h.='<section id="form-status" class="card"><h2>Status Borang</h2>';
   if($statusOrgs){
    $statusIds=array_keys($statusOrgs);
    $templates=Database::query($p,'SELECT t.id,t.title,t.status,t.organisation_id,o.name AS organisation_name,COUNT(s.id) AS total_submissions,SUM(CASE WHEN s.status=\'submitted\' THEN 1 ELSE 0 END) AS pending_submissions FROM eforms_templates t JOIN organisations o ON o.id=t.organisation_id LEFT JOIN eforms_versions v ON v.template_id=t.id LEFT JOIN eforms_submissions s ON s.version_id=v.id WHERE t.organisation_id IN ('.implode(',',array_fill(0,count($statusIds),'?')).') GROUP BY t.id,t.title,t.status,t.organisation_id,o.name ORDER BY t.id DESC LIMIT 100',$statusIds)->fetchAll();
    $h.='<div class="table-wrap"><table><thead><tr><th>Borang</th><th>Organisasi</th><th>Status</th><th>Submission</th><th>Tindakan</th></tr></thead><tbody>';
    foreach($templates as $template){
     $edit=$super||Authorization::allowed($p,$u,'eforms.templates.manage',(int)$template['organisation_id']);
     $actions='Lihat sahaja';
     if($edit){
      $actions='<a href="/eforms?studio='.$template['id'].'">Edit</a>';
      if($template['status']!=='published')$actions.=self::form('publish','<input type="hidden" name="id" value="'.$template['id'].'">','Terbit (Publish)');
     }
     $h.='<tr><td>'.self::e($template['title']).'</td><td>'.self::e($template['organisation_name']).'</td><td>'.self::e($template['status']).'</td><td>'.(int)$template['total_submissions'].' ('.(int)$template['pending_submissions'].' menunggu)</td><td>'.$actions.'</td></tr>';
    }
    $h.='</tbody></table></div>';
    if(!$templates)$h.='<p>Tiada template dalam skop ini.</p>';
   }else $h.='<p>Tiada status borang dalam skop akses anda.</p>';
   $h.='</section>';
  }
  return $h;
 }
 private static function submissionTable(array $rows,string $empty,bool $approval=false):string {
  if(!$rows)return '<p>'.self::e($empty).'</p>';
  $h='<div class="table-wrap"><table data-eforms-table><thead><tr><th>ID</th><th>Tajuk</th><th>Status</th><th>Kemaskini</th><th>Tindakan</th></tr></thead><tbody>';
  foreach($rows as $row)$h.='<tr><td>'.(int)$row['id'].'</td><td>'.self::e($row['title']).'</td><td>'.self::e($row['status']).'</td><td>'.self::e($row['updated_at']).'</td><td><a href="/eforms?submission='.(int)$row['id'].'">'.($approval?'Luluskan (Approve) / Semak':'Semak').'</a></td></tr>';
  return $h.'</tbody></table></div>';
 }
 private static function form(string $action,string $fields,string $label='Simpan',bool $upload=false):string {return '<form method="post"'.($upload?' enctype="multipart/form-data"':'').'><input type="hidden" name="csrf" value="'.Support::csrf().'"><input type="hidden" name="action" value="'.$action.'">'.$fields.'<button>'.$label.'</button></form>';}
 private static function select(string $name,string $label,array $rows,mixed $value=''):string {$h='<label>'.self::e($label).'<select name="'.self::e($name).'"><option value="">— Pilih —</option>';foreach($rows as $r)$h.='<option value="'.self::e($r['id']).'"'.((string)$r['id']===(string)$value?' selected':'').'>'.self::e($r['name']).'</option>';return $h.'</select></label>';}
 public static function handle(\PDO $p,?array $user):never {if(!$user)Support::redirect('/login');$u=(int)$user['id'];$message='';$error=false;$ready=(bool)Database::query($p,"SELECT 1 FROM information_schema.TABLES WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='eforms_templates'")->fetchColumn();try {$migrationPage=isset($_GET['visual_migration']);$packages=$migrationPage?null:PackageWeb::routes($p,$u);if($packages!==null)Ui::layout('Pusat Borang Digital',$packages,'<a href="/eforms">e-Forms</a>');$visual=$migrationPage?null:VisualWeb::routes($p,$u);if($visual!==null){Ui::layout('Smart Form Studio',$visual,'<a href="/eforms">e-Forms</a>');}if($_SERVER['REQUEST_METHOD']==='POST'){Support::checkCsrf();$action=Support::post('action',40);if($action==='migrate'){if(!Authorization::super($p,$u))throw new \RuntimeException('Super Admin diperlukan.');InstallationKey::verify($p,$u,Support::post('installation_key',12));if(($_POST['backup_confirmed']??'')!=='1'||!is_file(APP_ROOT.'/storage/installed.lock'))throw new \RuntimeException('Backup fail dan installation lock diperlukan.');$manifest=json_decode(file_get_contents(APP_ROOT.'/database/eforms-manifest.json'),true,512,JSON_THROW_ON_ERROR);foreach($manifest['files'] as $f){$file=APP_ROOT.'/'.$f['path'];if(is_link($file)||!is_file($file)||!hash_equals($f['sha256'],hash_file('sha256',$file)))throw new \RuntimeException('Integriti fail pemasangan gagal: '.$f['path']);}Migrations::plan($p);Backup::create($p,$u,bin2hex(random_bytes(16)));Migrations::apply($p,$u);unset($_SESSION['upgrade_key_auth']);Support::redirect('/eforms');}if(!$ready)throw new \RuntimeException('Migration belum lengkap.');$id=Core::id($_POST['id']??null,true);switch($action){case 'template':$org=Core::id($_POST['organisation_id']??null);$fields=json_decode(Support::post('fields_json',50000),true,64,JSON_THROW_ON_ERROR);$steps=json_decode(Support::post('workflow_json',5000),true,32,JSON_THROW_ON_ERROR);$id=Service::template($p,$u,$org,Support::post('title',190),$fields,$steps,($_POST['allow_self']??'')==='1',Support::post('acknowledgement',1000),$id);Support::redirect('/eforms?builder='.$id);case 'publish':Service::publish($p,$u,$id,($_POST['active']??'1')==='1');$message='Status borang dikemaskini.';break;case 'new':$id=Service::draft($p,$u,$id);Support::redirect('/eforms?submission='.$id);case 'save':case 'submit':Service::save($p,$u,$id,is_array($_POST['values']??null)?$_POST['values']:[],Core::id($_POST['revision']??null),$action==='submit',($_POST['ack']??'')==='1');Support::redirect('/eforms?submission='.$id);case 'delegate':Service::delegate($p,$u,$id,Core::id($_POST['delegate_to']??null),Support::post('reason',500),Core::id($_POST['revision']??null));Support::redirect('/eforms?submission='.$id);case 'decision':Service::decide($p,$u,$id,Support::post('decision',20),Support::post('reason',500),Core::id($_POST['revision']??null));Support::redirect('/eforms?submission='.$id);case 'attachment':Service::attachment($p,$u,$id,Support::post('field_key',40),$_FILES['file']??[],Core::id($_POST['revision']??null));Support::redirect('/eforms?submission='.$id);default:throw new \InvalidArgumentException('Tindakan tidak sah.');}}
 if(!$ready||$migrationPage){if(!Authorization::super($p,$u))throw new AccessDenied('Super Admin diperlukan.');$plan=Migrations::plan($p);$pending=array_filter($plan,fn($m)=>$m['status']==='pending');$h='<h2>Status migration e-Forms</h2><p>Semakan ini tidak menjalankan migration. Ledger dan checksum disemak melalui migration engine sedia ada.</p><ul>';foreach($plan as $m)$h.='<li>'.self::e($m['version']).' — '.self::e(strtoupper($m['status'])).'</li>';$h.='</ul>';if(!$pending){$h.='<p class="notice">Semua migration e-Forms telah APPLIED. Tiada tindakan pemasangan diperlukan.</p><a href="/eforms?packages=1">Buka Pusat Borang Digital</a>';}else{$h.='<p>Migration pending: '.count($pending).'. Fail yang disalin tidak bermakna database sudah dipasang. Backup automatik mesti berjaya sebelum migration.</p>'.self::form('migrate','<label>Installation Key 12 digit<input type="password" name="installation_key" inputmode="numeric" pattern="[0-9]{12}" minlength="12" maxlength="12" required autocomplete="off"></label><label><input type="checkbox" name="backup_confirmed" value="1" required>Saya telah backup fail dan meluluskan migration additive e-Forms.</label>','Backup automatik & jalankan migration');}}

 else {Core::module($p,'eforms');if(Packages::ready($p)&&(Authorization::super($p,$u)||Authorization::any($p,$u,'eforms.submissions.create'))){$packageNav='<p><a class="button" href="/eforms?library=1">Pusat Borang Digital</a> <a href="/eforms?packages=1">Import ZIP Borang</a></p>';}if(isset($_GET['pdf'])){$id=Core::id($_GET['pdf']);$bytes=Service::pdf($p,$u,$id);header('Content-Type: application/pdf');header('Content-Disposition: attachment; filename="eforms-'.$id.'.pdf"');header('Cache-Control: private, no-store');echo $bytes;exit;}if(isset($_GET['submission']))$h=self::submission($p,$u,Core::id($_GET['submission']));elseif(isset($_GET['builder']))$h=self::builder($p,$u,in_array($_GET['builder'],['new','0'],true)?null:Core::id($_GET['builder']));else $h=self::workspace($p,$u);if(!Visual::ready($p)&&Authorization::super($p,$u))$h='<p><a class="button" href="/eforms?visual_migration=1">Aktifkan migration Smart Form Studio</a></p>'.$h;}
 }catch(\Throwable $e){$error=true;$denied=$e instanceof AccessDenied||in_array($e->getMessage(),['Super Admin diperlukan.','Permission Form Builder diperlukan.','Admin Form Builder diperlukan.','Permission Admin borang diperlukan.'],true);http_response_code($e instanceof \PDOException?500:($denied?403:400));$message=$e instanceof \PDOException?'Permintaan gagal. Rujukan: '.Support::log($e):($e instanceof \JsonException?'Format definisi borang tidak sah.':$e->getMessage());$h='<p><a href="/eforms">Kembali ke e-Forms</a></p>';}
 Ui::layout('e-Forms',($message?'<p class="'.($error?'error':'notice').'" role="'.($error?'alert':'status').'">'.self::e($message).'</p>':'').($packageNav??'').($h??'').'<script type="module" src="/assets/eforms-inputs.mjs"></script><script src="/assets/eforms.js?v='.substr(hash_file('sha256',APP_ROOT.'/assets/eforms.js'),0,16).'" defer></script><link rel="stylesheet" href="/assets/eforms.css?v='.substr(hash_file('sha256',APP_ROOT.'/assets/eforms.css'),0,16).'">');}
 private static function orgs(\PDO $p,int $u,string $perm):array {if($perm==='submissions.create'){$out=[];foreach($p->query('SELECT id,name FROM organisations WHERE is_active=1 ORDER BY name')->fetchAll() as $o){try{Service::permit($p,$u,$perm,(int)$o['id']);$out[]=$o;}catch(\RuntimeException $e){}}return $out;}if(Authorization::super($p,$u))return $p->query('SELECT id,name FROM organisations WHERE is_active=1 ORDER BY name')->fetchAll();[$s,$a]=Authorization::scope($p,$u,'eforms.'.$perm,'o.id');return Database::query($p,'SELECT o.id,o.name FROM organisations o WHERE o.is_active=1 AND '.$s.' ORDER BY o.name',$a)->fetchAll();}
 private static function builder(\PDO $p,int $u,?int $id):string {$orgs=self::orgs($p,$u,'templates.manage');if(!$orgs)throw new \RuntimeException('Permission Form Builder diperlukan.');$r=$id?Database::query($p,'SELECT t.*,v.schema_json,v.workflow_json,v.acknowledgement,v.allow_self_approval FROM eforms_templates t JOIN eforms_versions v ON v.template_id=t.id WHERE t.id=? ORDER BY v.version DESC LIMIT 1',[$id])->fetch():null;if($id&&!$r)throw new \RuntimeException('Template tidak wujud.');if($r)Service::permit($p,$u,'templates.manage',(int)$r['organisation_id']);$staff=Database::query($p,'SELECT u.id,s.full_name AS name,s.organisation_id FROM users u JOIN staff_profiles s ON s.staff_identity_id=u.staff_identity_id WHERE u.is_active=1 ORDER BY s.full_name')->fetchAll();$staff=array_values(array_filter($staff,fn($r)=>in_array($r['organisation_id'],array_column($orgs,'id'))));$data=['fields'=>$r?json_decode($r['schema_json'],true):[],'steps'=>$r?json_decode($r['workflow_json'],true):[],'staff'=>$staff,'types'=>Schema::TYPES];$f='<input type="hidden" name="id" value="'.($id?:'').'">'.self::select('organisation_id','Skop organisasi',$orgs,$r['organisation_id']??'').'<label>Tajuk borang<input name="title" required maxlength="190" value="'.self::e($r['title']??'').'"></label><div data-builder-fields></div><button type="button" data-add-field>Tambah medan</button><h3>Workflow</h3><p>Setiap pelulus mesti mempunyai role e-Forms reviewer/admin dalam skop organisasi. Langkah akhir wajib approval.</p><div data-builder-steps></div><button type="button" data-add-step>Tambah penyemak/pelulus</button><input type="hidden" name="fields_json"><input type="hidden" name="workflow_json"><label><input type="checkbox" name="allow_self" value="1"'.(!empty($r['allow_self_approval'])?' checked':'').'>Polisi membenarkan self-approval</label><label>Perakuan digital<textarea name="acknowledgement" required maxlength="1000">'.self::e($r['acknowledgement']??'Saya mengesahkan maklumat yang diberikan adalah benar.').'</textarea></label>';$h='<h2>Form Builder</h2><p>Simpan mencipta versi baharu; submission lama kekal pada versi asal.</p><script type="application/json" id="eforms-builder-data">'.json_encode($data,JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT).'</script>'.str_replace('<form ','<form data-eforms-builder ',self::form('template',$f,'Simpan versi draft'));if($r)$h.='<p>Status: '.self::e($r['status']).'</p>'.self::form('publish','<input type="hidden" name="id" value="'.$id.'">','Publish versi terkini').self::form('publish','<input type="hidden" name="id" value="'.$id.'"><input type="hidden" name="active" value="0">','Nyahaktifkan template');return $h;}
 private static function submission(\PDO $p,int $u,int $id):string {$r=Service::get($p,$u,$id);$owner=(int)$r['applicant_id']===$u;$editable=$owner&&in_array($r['status'],['draft','returned'],true);$f='<input type="hidden" name="id" value="'.$id.'"><input type="hidden" name="revision" value="'.$r['revision'].'">';$h='<h2>'.self::e($r['title']).'</h2><p>Permohonan #'.$id.' · '.self::e($r['status']).' · Versi '.$r['version'].'</p><a href="/eforms?pdf='.$id.'">Muat turun PDF</a>';if(Visual::ready($p)&&($vb=Visual::binding($p,(int)$r['version_id']))&&$vb['source_id'])$h.='<p><a class="button" href="/eforms?print_original='.$id.'">Cetak PDF asal / lengkap</a></p>';$auto=Visual::autofill($p,$u);$files=array_column($r['files'],'document_id','field_key');foreach($r['fields'] as $field){$k=$field['key'];$v=$r['values'][$k]??($editable?$auto[$field['autofill']??'']??'':'');$label=self::e($field['label']).($field['required']?' *':'');$attrs=' data-eforms-condition="'.self::e(json_encode($field['condition'])).'"';$control='';$name='values['.$k.']';if(!$editable){if(Schema::visible($field,$r['values']))$f.='<p><strong>'.$label.'</strong>: '.self::e(is_array($v)?json_encode($v,JSON_UNESCAPED_UNICODE):$v).'</p>';continue;}$extended=VisualWeb::field($field,$v,$editable);if($extended!==null){$f.='<div'.$attrs.'>'.$extended.'</div>';continue;}switch($field['type']){case 'section':$control='<h3>'.$label.'</h3>';break;case 'file':$control='<p>'.$label.' — Simpan draft dahulu, kemudian upload di bawah.</p>';break;case 'textarea':$control='<label>'.$label.'<textarea name="'.$name.'" maxlength="10000">'.self::e($v).'</textarea></label>';break;case 'radio':$control='<fieldset><legend>'.$label.'</legend>';foreach($field['options'] as $option)$control.='<label><input type="radio" name="'.$name.'" value="'.self::e($option).'"'.($v===$option?' checked':'').'>'.self::e($option).'</label>';$control.='</fieldset>';break;case 'dropdown':$control=self::select($name,$field['label'],array_map(fn($o)=>['id'=>$o,'name'=>$o],$field['options']),$v);break;case 'organisation':case 'staff':$rows=Database::query($p,$field['type']==='organisation'?'SELECT o.id,o.name FROM organisations o JOIN organisation_hierarchy h ON h.descendant_id=o.id WHERE h.ancestor_id=? AND o.is_active=1':'SELECT s.staff_identity_id AS id,s.full_name AS name FROM staff_profiles s JOIN organisation_hierarchy h ON h.descendant_id=s.organisation_id WHERE h.ancestor_id=?',[$r['organisation_id']])->fetchAll();$control=self::select($name,$field['label'],$rows,$v);break;case 'checkbox':$control='<label><input type="checkbox" name="'.$name.'" value="1"'.($v==='1'?' checked':'').'>'.$label.'</label>';break;default:$control='<label>'.$label.'<input name="'.$name.'" type="'.$field['type'].'"'.($field['type']==='number'?' step="any"':'').' value="'.self::e($v).'" maxlength="1000"></label>';}$f.='<div'.$attrs.'>'.$control.'</div>';}
 if($editable)$h.=str_replace('</form>','<label><input type="checkbox" name="ack" value="1">'.self::e($r['acknowledgement']).'</label><button name="action" value="submit">Hantar permohonan</button></form>',self::form('save',$f,'Simpan draft'));else $h.='<section class="card">'.$f.'</section>';
 foreach($r['fields'] as $field)if($field['type']==='file'&&Schema::visible($field,$r['values'])){if(isset($files[$field['key']]))$h.='<p><a href="/download?id='.$files[$field['key']].'&amp;version=1">Lampiran: '.self::e($field['label']).'</a></p>';elseif($editable)$h.=self::form('attachment','<input type="hidden" name="id" value="'.$id.'"><input type="hidden" name="revision" value="'.$r['revision'].'"><input type="hidden" name="field_key" value="'.$field['key'].'"><label>'.self::e($field['label']).'<input name="file" type="file" accept="application/pdf,image/jpeg,image/png" required></label><p>PDF/JPEG/PNG, maksimum 5 MB.</p>','Upload lampiran',true);}
 $canDecide=$r['status']==='submitted'&&(int)($r['steps'][$r['step_index']]['user_id']??0)===$u&&(Authorization::super($p,$u)||Authorization::allowed($p,$u,'eforms.submissions.review',(int)$r['organisation_id']));if($canDecide)$h.=self::form('decision','<input type="hidden" name="id" value="'.$id.'"><input type="hidden" name="revision" value="'.$r['revision'].'">'.self::select('decision','Keputusan',[['id'=>'approve','name'=>'Sahkan / Lulus'],['id'=>'return','name'=>'Kembalikan untuk pembetulan'],['id'=>'reject','name'=>'Tolak']]).'<label>Sebab<textarea name="reason" required maxlength="500"></textarea></label>','Simpan keputusan');if(Visual::ready($p)&&$canDecide){$reviewers=[];foreach(Database::query($p,'SELECT u.id,s.full_name AS name FROM users u JOIN staff_profiles s ON s.staff_identity_id=u.staff_identity_id WHERE u.is_active=1')->fetchAll() as $candidate){try{Service::permit($p,(int)$candidate['id'],'submissions.review',(int)$r['organisation_id']);if((int)$candidate['id']!==$u&&(int)$candidate['id']!==(int)$r['applicant_id'])$reviewers[]=$candidate;}catch(\RuntimeException $e){}}$h.=self::form('delegate','<input type="hidden" name="id" value="'.$id.'"><input type="hidden" name="revision" value="'.$r['revision'].'">'.self::select('delegate_to','Delegate dalam skop',$reviewers).'<label>Sebab<textarea name="reason" required maxlength="500"></textarea></label>','Delegate semakan');}$h.='<h3>Audit &amp; Tracking</h3>';foreach(Database::query($p,'SELECT action,reason,created_at FROM eforms_history WHERE submission_id=? ORDER BY id',[$id])->fetchAll() as $r)$h.='<p>'.self::e($r['created_at'].' · '.$r['action'].' · '.$r['reason']).'</p>';return $h;}
}
